package com.hospital.dao;
import com.hospital.model.*;import com.hospital.util.DBConnection;import java.sql.*;import java.math.BigDecimal;import java.util.*;
public class BillingDAO {
 public long create(long appointment,BigDecimal subtotal,BigDecimal discount,String description,long user)throws SQLException{if(discount.compareTo(subtotal)>0)throw new IllegalArgumentException("Discount cannot exceed subtotal.");BigDecimal total=subtotal.subtract(discount);try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{long patient;try(PreparedStatement p=c.prepareStatement("SELECT patient_id,status FROM appointments WHERE appointment_id=? FOR UPDATE")){p.setLong(1,appointment);try(ResultSet r=p.executeQuery()){if(!r.next()||!"COMPLETED".equals(r.getString("status")))throw new SQLException("A completed appointment is required for billing.");patient=r.getLong(1);}}long id;try(PreparedStatement p=c.prepareStatement("INSERT INTO bills(appointment_id,patient_id,subtotal,discount,total,created_by) VALUES(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,appointment);p.setLong(2,patient);p.setBigDecimal(3,subtotal);p.setBigDecimal(4,discount);p.setBigDecimal(5,total);p.setLong(6,user);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getLong(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO bill_items(bill_id,description,quantity,unit_price,amount) VALUES(?, ?,1,?,?)")){p.setLong(1,id);p.setString(2,description);p.setBigDecimal(3,subtotal);p.setBigDecimal(4,subtotal);p.executeUpdate();}c.commit();return id;}catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
 public Bill find(long id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM bills WHERE bill_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?new Bill(r.getLong("bill_id"),r.getLong("appointment_id"),r.getLong("patient_id"),r.getBigDecimal("subtotal"),r.getBigDecimal("discount"),r.getBigDecimal("total"),r.getBigDecimal("paid_amount"),r.getString("status")):null;}}}
 public List<String> unpaid()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT bill_id,patient_id,total,paid_amount,status FROM bills WHERE status<>'PAID' ORDER BY issued_at");ResultSet r=p.executeQuery()){List<String>x=new ArrayList<>();while(r.next())x.add(String.format("Bill %d | patient %d | total %s | paid %s | %s",r.getLong(1),r.getLong(2),r.getBigDecimal(3),r.getBigDecimal(4),r.getString(5)));return x;}}
}
